/* ===================== BÀI 30 · Dịch vụ DOS trong profile DOS ===================== */
/* Bài 30 · Dịch vụ DOS trong profile DOS (AMTS-EMB-002-M08-L02, X86-030) — sinh bởi tools/author/mpu8086/l30.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P30=[{"label": "Ví dụ: in chuỗi (09h) và in ký tự (02h)", "code": "; Ví dụ 1: in chuỗi (hàm 09h) và in ký tự (hàm 02h)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'Xin chao$'             ; 09h in tới dấu $\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET msg          ; DS:DX trỏ chuỗi\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, '!'                 ; DL = ký tự cần in\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai cách in: hàm 09h in Xin chao (DS:DX trỏ msg, dừng ở $, không in $), hàm 02h in ký tự trong DL. Mỗi lệnh INT 21h chỉ tính 51 chu kỳ. Xem AL sau mỗi lần gọi: 24h sau hàm 09h, 21h ('!') sau hàm 02h (giá trị theo Ralf Brown's Interrupt List, không nên dựa vào). Đoán trước: sau INT 21h hàm 09h, AH còn là 09h không? Đáp án có."}, {"label": "Ví dụ: nhập một dòng bằng hàm 0Ah", "code": "; Ví dụ 2: nhập một dòng bằng hàm 0Ah\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      10                      ; byte 0: tối đa 10 ký tự, kể cả Enter\n        DB      ?                       ; byte 1: DOS ghi số ký tự đã nhập\n        DB      10 DUP(?)               ; từ byte 2: các ký tự, rồi 0Dh\ntb      DB      10, 'So ky tu: $'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET buf\n        MOV     AH, 0AH\n        INT     21H                     ; đọc tới phím Enter\n        MOV     DX, OFFSET tb           ; 10 = LF: xuống dòng\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, buf+1               ; số ký tự (không tính Enter)\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "An\n", "note": "Gõ An rồi Enter (đã điền sẵn ở ô nhập). Mở phần Bộ nhớ ở đoạn dữ liệu: buf = 0A 02 41 6E 0D. Hàm 0Ah tự hiện các phím và in CR khi gặp Enter (con trỏ về đầu dòng), nên chuỗi tb bắt đầu bằng byte 10 (LF) để xuống dòng. MOV DL, buf+1 lấy số ký tự (2). Đoán trước: sau hàm 0Ah, byte buf+1 bằng bao nhiêu? Đáp án 02h."}, {"label": "Ví dụ: hàm 08h không hiện, tự in *", "code": "; Ví dụ 3: hàm 08h không hiện phím, tự in dấu *\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmk      DB      3 DUP(?)                ; ba phím của mật khẩu\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, 0\nDOC:\n        MOV     AH, 08H                 ; đọc phím, không hiện\n        INT     21H\n        MOV     mk[BX], AL\n        MOV     DL, '*'                 ; tự in dấu * thay phím\n        MOV     AH, 02H\n        INT     21H\n        INC     BX\n        CMP     BX, 3\n        JB      DOC\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "abc", "note": "Hàm 08h đọc phím mà không hiện; chương trình tự in * cho mỗi phím và cất phím vào mk[BX] (MOV mk[BX], AL: 9 + EA 9 = 18 chu kỳ). Gõ abc: màn hình chỉ có ***, biến mk = 61 62 63. Đoán trước: sau lần INT 21h hàm 08h đầu tiên, AL bằng bao nhiêu? Đáp án 61h ('a')."}, {"label": "Lỗi: chuỗi thiếu dấu $", "code": "; Ví dụ 4: LỖI - chuỗi thiếu dấu $\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nm1      DB      'Xin chao'              ; quên '$'\nm2      DB      'Tam biet$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET m1\n        MOV     AH, 09H\n        INT     21H                     ; in tới $ đầu tiên gặp được\n        MOV     DX, OFFSET m2\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: m1 thiếu '$'. Hàm 09h in Xin chao rồi in luôn m2 nằm ngay sau trong bộ nhớ, tới dấu $ của m2. Lần gọi thứ hai in m2 lần nữa: màn hình Xin chaoTam bietTam biet. Sửa: m1 DB 'Xin chao$'. Đoán trước: lần gọi hàm 09h đầu tiên dừng ở byte nào? Đáp án dấu $ cuối m2."}, {"label": "Ví dụ: hàm 4Ch trả mã thoát", "code": "; Ví dụ 5: kết thúc bằng hàm 4Ch với mã thoát\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 01H                 ; đọc một chữ số, có hiện\n        INT     21H\n        SUB     AL, '0'                 ; AL = giá trị chữ số\n        MOV     AH, 4CH                 ; AL là mã thoát\n        INT     21H                     ; DOS: ERRORLEVEL = AL\nMAIN    ENDP\n        END     MAIN\n", "input": "7", "note": "Gõ 7. Hàm 01h hiện phím và trả AL = 37h; SUB AL, '0' cho AL = 7; MOV AH, 4Ch / INT 21h kết thúc với mã thoát 7 (phần kết quả của trình mô phỏng hiện mã thoát). Trong tệp lệnh DOS, IF ERRORLEVEL 7 đúng sau chương trình này. Đoán trước: ngay trước INT 21h cuối, AX bằng bao nhiêu? Đáp án 4C07h."}, {"label": "Bẫy: bộ đệm hàm 0Ah đầy", "code": "; Ví dụ 6: BẪY - bộ đệm hàm 0Ah đầy\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      4                       ; chỉ chứa 3 ký tự + Enter\n        DB      ?\n        DB      4 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET buf\n        MOV     AH, 0AH\n        INT     21H                     ; gõ ABCDEF rồi Enter\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "ABCDEF\n", "note": "Bẫy: byte 0 của bộ đệm là 4 nên hàm 0Ah chỉ giữ 3 ký tự (4 tính cả Enter). Gõ ABCDEF rồi Enter: bộ đệm 04 03 41 42 43 0D, ba phím D, E, F bị bỏ (DOS thật kêu bíp; trình mô phỏng bỏ im lặng). Sửa: khai báo byte 0 = số ký tự tối đa + 1 và bộ đệm đủ max + 2 byte. Đoán trước: byte buf+1 bằng bao nhiêu? Đáp án 03h."}, {"label": "Lỗi: quên đặt lại AH trước INT 21h", "code": "; Ví dụ 7: LỖI - dùng lại AH của lần gọi trước\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'Chao$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET msg\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, '!'                 ; muốn in '!' nhưng quên\n        INT     21H                     ; MOV AH, 02h: AH vẫn là 09h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: sau hàm 09h, AH vẫn là 09h. Lệnh INT 21h thứ hai lẽ ra in '!' (hàm 02h) nhưng thực chất gọi lại hàm 09h, và MOV DL, '!' đã đổi DX thành 0021h: DOS in từ DS:0021h, vùng không có $, trình mô phỏng dừng sau 4000 ký tự. Sửa: thêm MOV AH, 02h trước INT 21h. Đoán trước: ngay trước INT 21h thứ hai, AX bằng bao nhiêu? Đáp án 0924h."}, {"label": "Ví dụ: năm lần hàm 02h so với một lần 09h", "code": "; Ví dụ 8: in 5 ký tự - năm lần 02h so với một lần 09h\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ns       DB      'HELLO$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET s            ; cách 1: từng ký tự\n        MOV     CX, 5\n        MOV     AH, 02H\nLAP:\n        MOV     DL, [SI]\n        INT     21H\n        INC     SI\n        LOOP    LAP\n        MOV     DX, OFFSET s            ; cách 2: một lần gọi\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng chuỗi HELLO in hai lần. Cách 1: vòng LOOP gọi hàm 02h 5 lần, mỗi ký tự 13 + 51 + 2 + 17 = 83 chu kỳ phía chương trình. Cách 2: một lần hàm 09h, 4 + 4 + 51 = 59 chu kỳ. Trên máy thật mỗi lần gọi còn tốn thêm thời gian bên trong DOS mà trình mô phỏng không đo. Đoán trước: lệnh INT 21h trong vòng chạy bao nhiêu lần? Đáp án 5."}];
const sim30=makeX86Sim(document.getElementById("x86-l30"),{id:"s30",presets:P30,file:"BAI30.ASM"});
makeX86Ex(document.getElementById("ex-l30"),sim30,[{"t": "Chào theo tên", "d": "In Ten: , đọc tên bằng INT 21h hàm 0Ah vào bộ đệm buf (tối đa 15 ký tự), rồi in Chao <tên>! ở dòng dưới. Code mẫu đã có đủ các lần gọi hàm 09h nhưng tên in ra bị lẫn ký tự lạ: chuỗi tên trong bộ đệm kết thúc bằng 0Dh chứ không phải '$'. Hãy ghi '$' đè lên byte 0Dh ngay sau ký tự cuối của tên. Kết thúc bằng INT 21h hàm 4Ch. Tên có thể rỗng (chỉ nhấn Enter) hoặc dài hơn 15 ký tự (DOS chỉ giữ 15 ký tự đầu).", "start": "; Bài tập 1: chào theo tên (hàm 0Ah, 09h)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhoi     DB      'Ten: $'\nbuf     DB      16                      ; tối đa 15 ký tự + Enter\n        DB      ?\nten     DB      17 DUP(?)\nchao    DB      10, 'Chao $'            ; 10 = LF: xuống dòng\nhet     DB      '!$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET hoi\n        MOV     AH, 09H\n        INT     21H\n        MOV     DX, OFFSET buf\n        MOV     AH, 0AH\n        INT     21H\n; TODO: đặt '$' ngay sau ký tự cuối của tên\n        MOV     DX, OFFSET chao\n        MOV     AH, 09H\n        INT     21H\n        MOV     DX, OFFSET ten\n        MOV     AH, 09H\n        INT     21H\n        MOV     DX, OFFSET het\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "An", "out": "Ten: An\r\nChao An!"}, {"in": "Binh", "out": "Ten: Binh\r\nChao Binh!"}, {"in": "", "out": "Ten: \r\nChao !"}, {"in": "Nguyen Van A", "out": "Ten: Nguyen Van A\r\nChao Nguyen Van A!"}, {"in": "ABCDEFGHIJKLMNOPQR", "out": "Ten: ABCDEFGHIJKLMNO\r\nChao ABCDEFGHIJKLMNO!"}, {"in": "x y", "out": "Ten: x y\r\nChao x y!"}]}, {"t": "Sửa chương trình in dòng đảo ngược", "d": "Đọc một dòng (tối đa 20 ký tự) bằng INT 21h hàm 0Ah, xuống dòng rồi in dòng đó theo thứ tự ngược bằng hàm 02h. Code mẫu chạy được nhưng in sai: ký tự đầu tiên bị thiếu và in ra một ký tự 0Dh. Tìm và sửa lỗi chỉ số. Dòng rỗng thì chỉ xuống dòng, không in gì. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: in dòng đảo ngược (có lỗi cần sửa)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      21                      ; tối đa 20 ký tự + Enter\n        DB      ?\ndong    DB      21 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET buf\n        MOV     AH, 0AH\n        INT     21H\n        MOV     DL, 10                  ; xuống dòng\n        MOV     AH, 02H\n        INT     21H\n        MOV     CL, buf+1\n        MOV     CH, 0                   ; CX = số ký tự\n        JCXZ    XONG\n        MOV     SI, CX                  ; LỖI: dong[CX] là 0Dh\nLAP:\n        MOV     DL, dong[SI]\n        MOV     AH, 02H\n        INT     21H\n        DEC     SI\n        LOOP    LAP\nXONG:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "abc", "out": "abc\r\ncba"}, {"in": "", "out": ""}, {"in": "8086", "out": "8086\r\n6808"}, {"in": "A man", "out": "A man\r\nnam A"}, {"in": "0123456789abcdefghijKLM", "out": "0123456789abcdefghij\r\njihgfedcba9876543210"}, {"in": "Z", "out": "Z\r\nZ"}]}, {"t": "In hoa cả dòng, ít lời gọi DOS", "d": "Đọc một dòng (tối đa 40 ký tự, không chứa ký tự '$') bằng INT 21h hàm 0Ah, xuống dòng, rồi in lại dòng đó với chữ thường a–z đổi thành chữ hoa (ký tự khác giữ nguyên). Code mẫu đúng nhưng gọi INT 21h hàm 02h cho từng ký tự. Viết lại để chương trình chạy không quá 3000 chu kỳ ở test dài nhất (40 ký tự) và mã không quá 63 byte. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: in hoa cả dòng - đúng nhưng chậm\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      41                      ; tối đa 40 ký tự + Enter\n        DB      ?\ndong    DB      41 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, OFFSET buf\n        MOV     AH, 0AH\n        INT     21H\n        MOV     DL, 10\n        MOV     AH, 02H\n        INT     21H\n        MOV     CL, buf+1\n        MOV     CH, 0\n        JCXZ    XONG\n        MOV     SI, OFFSET dong\nLAP:\n        MOV     DL, [SI]                ; mỗi ký tự một lần INT 21h\n        CMP     DL, 'a'\n        JB      IN1\n        CMP     DL, 'z'\n        JA      IN1\n        SUB     DL, 20H\nIN1:\n        MOV     AH, 02H\n        INT     21H\n        INC     SI\n        LOOP    LAP\nXONG:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "Xin chao 8086", "out": "Xin chao 8086\r\nXIN CHAO 8086"}, {"in": "", "out": ""}, {"in": "abcdefghijklmnopqrstuvwxyz{`@[", "out": "abcdefghijklmnopqrstuvwxyz{`@[\r\nABCDEFGHIJKLMNOPQRSTUVWXYZ{`@["}, {"in": "DA HOA", "out": "DA HOA\r\nDA HOA"}, {"in": "mot dong rat dai de thu bo dem bon muoi ky tu nhe", "out": "mot dong rat dai de thu bo dem bon muoi \r\nMOT DONG RAT DAI DE THU BO DEM BON MUOI "}, {"in": "q", "out": "q\r\nQ"}], "perf": {"cycles": 3000, "bytes": 63}}]);

makeQuiz("quiz30","score30",[{"q": "Bộ đệm khai báo <code>buf DB 6, ?, 6 DUP(?)<\/code>. Người dùng gõ <code>Hello World<\/code> rồi Enter khi chương trình gọi hàm 0Ah. Sáu byte đầu của buf là gì?", "o": ["06 05 48 65 6C 6C (và byte kế tiếp 6F, rồi 0D)", "06 0B 48 65 6C 6C (DOS ghi đủ 11 ký tự)", "06 06 48 65 6C 6C (DOS ghi 6 ký tự, không có 0D)", "05 06 48 65 6C 6C (DOS đổi byte 0 thành số ký tự)"], "a": 0, "e": "Byte 0 = 6 là tối đa kể cả Enter, nên DOS giữ 5 ký tự “Hello”, ghi byte 1 = 5 và 0Dh ngay sau ký tự cuối; phím thừa bị bỏ. Byte 0 không bị DOS đổi."}, {"q": "Đoạn code sau in gì (msg là <code>'Chao$'<\/code>)?<pre class=\"mp-asm\">        MOV     DX, OFFSET msg\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, '!'\n        INT     21H<\/pre>", "o": ["Chao, rồi lại gọi hàm 09h với DX = 0021h: in các byte từ DS:0021h tới dấu $", "Chao!", "Chao rồi dấu ! vì INT 21h tự nhận ra DL đã đổi", "Chao Chao, vì hàm 09h in lại msg"], "a": 0, "e": "AH vẫn là 09h nên lần gọi thứ hai là hàm 09h; MOV DL, '!' đổi byte thấp của DX nên DX = 0021h (offset của msg là 0000h). Phải đặt lại MOV AH, 02h (Ví dụ 7)."}, {"q": "Chương trình cần báo cho tệp lệnh .BAT là đã gặp lỗi số 3. Cách kết thúc nào đúng?", "o": ["<code>MOV AL, 3<\/code> / <code>INT 20h<\/code>", "<code>MOV AX, 0003h<\/code> / <code>INT 21h<\/code>", "<code>MOV AX, 4C03h<\/code> / <code>INT 21h<\/code>", "<code>MOV AH, 4Ch<\/code> / <code>MOV AL, 3<\/code> / <code>RET<\/code>"], "a": 2, "e": "Hàm 4Ch lấy mã thoát trong AL. INT 20h luôn trả mã 0 (và cần CS = PSP); AX = 0003h gọi hàm 00h; RET không phải lời gọi DOS."}, {"q": "Cần đọc 4 chữ số mã PIN: không hiện lên màn hình và không cho người dùng bấm Ctrl-C để thoát ngang. Hàm nào phù hợp nhất?", "o": ["Hàm 01h", "Hàm 08h", "Hàm 0Ah", "Hàm 07h"], "a": 3, "e": "07h: không hiện, không kiểm Ctrl-C. 08h không hiện nhưng có kiểm Ctrl-C; 01h và 0Ah hiện phím lên màn hình."}, {"q": "Chương trình in chữ bằng INT 21h chạy đúng trên DOSBox-X được nạp vào EPROM của một bo 8086 tự thiết kế (không có DOS). Điều gì xảy ra ở lệnh INT 21h đầu tiên?", "o": ["Chữ vẫn hiện ra vì INT 21h là lệnh của CPU 8086", "Trình dịch đã báo lỗi vì không có DOS lúc dịch", "CPU nhảy theo vectơ 21h trong RAM, vốn chưa được ai ghi: chạy lạc tới địa chỉ bất kỳ", "CPU bỏ qua INT 21h và chạy tiếp lệnh sau"], "a": 2, "e": "INT là lệnh của CPU nhưng dịch vụ in chữ là của DOS, do DOS cài vào RAM và ghi vectơ. Trên bo không có DOS, bảng vectơ (RAM) không được khởi tạo; chương trình phải tự lập trình ngoại vi hoặc tự cài vectơ."}]);

